// producer
wait(empty);   // block until a slot is free
wait(mutex);   // get exclusive access to the buffer
add_item();
signal(mutex); // release exclusive access
signal(full);  // announce one more filled slot

// consumer
wait(full);    // block until an item exists
wait(mutex);   // get exclusive access to the buffer
remove_item();
signal(mutex); // release exclusive access
signal(empty); // announce one more free slot

